<body>
    <div class="container">
        <div class="header">
            <h1>حجز موعد</h1>
        </div>

        <div class="doctor-section">
            <div class="doctor-info">
                <h2>د. فاطمة المنصوري</h2>
                <p>أخصائية طب الأسرة</p>
            </div>
        </div>

        <div class="calendar-header">
            <div class="month-nav">
                <button class="nav-btn" id="nextMonth">›</button>
                <span class="month-title" id="monthTitle">أكتوبر 2024</span>
                <button class="nav-btn" id="prevMonth">‹</button>
            </div>
        </div>

        <div class="weekdays" id="weekdays"></div>
        <div class="days-grid" id="daysGrid"></div>

        <div class="time-slots-container">
            <div class="time-slots-title">اختر وقت الحجز</div>
            <div class="time-slots" id="timeSlots"></div>
        </div>

        <button class="confirm-btn" id="confirmBtn" disabled>تأكيد الحجز</button>
    </div>

    <script>
        const arabicMonths = [
            "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
            "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
        ];

        const arabicWeekdays = ["س", "أ", "ح", "ث", "ج", "ب", "أ"];

        let currentDate = new Date();
        let selectedDate = null;
        let selectedTime = null;

        const monthTitle = document.getElementById("monthTitle");
        const weekdaysEl = document.getElementById("weekdays");
        const daysGridEl = document.getElementById("daysGrid");
        const timeSlotsEl = document.getElementById("timeSlots");
        const confirmBtn = document.getElementById("confirmBtn");
        const prevMonthBtn = document.getElementById("prevMonth");
        const nextMonthBtn = document.getElementById("nextMonth");

        function renderWeekdays() {
            weekdaysEl.innerHTML = "";
            arabicWeekdays.forEach(day => {
                const div = document.createElement("div");
                div.className = "weekday";
                div.textContent = day;
                weekdaysEl.appendChild(div);
            });
        }

        function renderCalendar() {
            const year = currentDate.getFullYear();
            const month = currentDate.getMonth();
            const today = new Date();

            monthTitle.textContent = `${arabicMonths[month]} ${year}`;

            daysGridEl.innerHTML = "";

            const firstDay = new Date(year, month, 1);
            const lastDayPrev = new Date(year, month, 0);
            const startDate = firstDay.getDay();

            let startOffset = (startDate - 6 + 7) % 7;

            const daysInMonth = lastDayPrev.getDate();

            const totalCells = Math.ceil((startOffset + daysInMonth) / 7) * 7;

            for (let i = 0; i < totalCells; i++) {
                const dayCell = document.createElement("div");
                dayCell.className = "day-cell";

                const dayNumber = i - startOffset + 1;

                if (i < startOffset) {
                    dayCell.classList.add("other-month");
                    dayCell.textContent = "";
                } else if (dayNumber > daysInMonth) {
                    dayCell.classList.add("other-month");
                    dayCell.textContent = "";
                } else {
                    dayCell.textContent = dayNumber;

                    const cellDate = new Date(year, month, dayNumber);

                    if (
                        today.getDate() === dayNumber &&
                        today.getMonth() === month &&
                        today.getFullYear() === year
                    ) {
                        dayCell.classList.add("current-day");
                    }

                    if (
                        selectedDate &&
                        selectedDate.getDate() === dayNumber &&
                        selectedDate.getMonth() === month &&
                        selectedDate.getFullYear() === year
                    ) {
                        dayCell.classList.add("selected");
                    }

                    dayCell.addEventListener("click", () => {
                        document.querySelectorAll(".day-cell").forEach(c => c.classList.remove("selected"));
                        dayCell.classList.add("selected");
                        selectedDate = new Date(year, month, dayNumber);
                        updateConfirmButton();
                    });
                }

                daysGridEl.appendChild(dayCell);
            }
        }

        function renderTimeSlots() {
            timeSlotsEl.innerHTML = "";
            const slots = [
                "09:00", "09:30", "10:00", "10:30",
                "11:00", "11:30", "12:00"
            ];

            slots.forEach(slot => {
                const btn = document.createElement("div");
                btn.className = "time-slot";
                btn.textContent = slot;
                btn.addEventListener("click", () => {
                    document.querySelectorAll(".time-slot").forEach(s => s.classList.remove("selected"));
                    btn.classList.add("selected");
                    selectedTime = slot;
                    updateConfirmButton();
                });
                timeSlotsEl.appendChild(btn);
            });
        }

        function updateConfirmButton() {
            if (selectedDate && selectedTime) {
                confirmBtn.disabled = false;
            } else {
                confirmBtn.disabled = true;
            }
        }

        prevMonthBtn.addEventListener("click", () => {
            currentDate.setMonth(currentDate.getMonth() - 1);
            renderCalendar();
        });

        nextMonthBtn.addEventListener("click", () => {
            currentDate.setMonth(currentDate.getMonth() + 1);
            renderCalendar();
        });

        confirmBtn.addEventListener("click", () => {
            if (selectedDate && selectedTime) {
                alert(`تم حجز موعد مع د. فاطمة المنصوري في تاريخ ${selectedDate.toLocaleDateString('ar-EG')} الساعة ${selectedTime}`);
            }
        });

        renderWeekdays();
        renderCalendar();
        renderTimeSlots();
    </script>
</body>
</html>
